import { expect, test, uniqueName } from "../../fixtures";

test("Create a vendor", { tag: "@VEN-01" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const name = uniqueName("Acme Freight");

  // Act
  const res = await member.post("/api/vendors", {
    data: { name, category: "logistics", contact_email: "ops@acmefreight.example" },
  });

  // Assert
  expect(res.status(), await res.text()).toBe(201);
  const vendor = await res.json();
  expect(vendor.status, JSON.stringify(vendor)).toBe("draft");
  expect(vendor.name).toBe(name);
  expect(vendor.category).toBe("logistics");

  await expect.poll(async () => {
    const audit = await member.get(`/api/vendors/${vendor.id}/audit`);
    if (audit.status() !== 200) return [];
    const body = (await audit.json()) as { items: { action: string }[] };
    return body.items.map((e) => e.action);
  }, { message: "audit event vendor.created recorded" }).toContain("vendor.created");
});
